html:
{%- set data = get_bundle_tickets(doc.name) -%}
{%- set thermal = data.format == "thermal" -%}
<style>
	.vt-tickets { font-family: Inter, "Helvetica Neue", Arial, sans-serif; color: #111; }
	.vt-ticket { box-sizing: border-box; border: 1px dashed #999; padding: 3mm 4mm; page-break-inside: avoid; break-inside: avoid; }
	.vt-ticket__head { display: flex; justify-content: space-between; align-items: baseline; gap: 2mm; font-size: 9pt; white-space: nowrap; }
	.vt-ticket__job { font-weight: 700; font-size: 11pt; }
	.vt-ticket__barcode { margin: 1.5mm 0 0.5mm; }
	.vt-ticket__barcode svg { display: block; width: 100%; height: 13mm; }
	.vt-ticket__code { text-align: center; font-family: "DejaVu Sans Mono", monospace; font-size: 9pt; letter-spacing: 0.5px; }
	.vt-ticket__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.5mm 3mm; margin-top: 1.5mm; font-size: 8.5pt; }
	.vt-ticket__grid b { font-weight: 700; }
	.vt-ticket__qty { font-size: 13pt; font-weight: 700; }
	/* A4: two tickets per row (about 90 x 45 mm each), so every field stays on the ticket. */
	.vt-tickets--a4 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4mm; }
	.vt-tickets--a4 .vt-ticket { min-height: 45mm; }
	.vt-empty-tickets { padding: 20mm; text-align: center; color: #666; }
{%- if thermal %}
	@page { size: 4in 2in; margin: 0; }
	.print-format { width: 4in !important; max-width: 4in !important; min-height: 0 !important; padding: 0 !important; margin: 0 auto !important; }
	.vt-tickets--thermal .vt-ticket { width: 4in; height: 2in; border: 0; padding: 0.12in 0.16in; page-break-after: always; break-after: page; }
	.vt-tickets--thermal .vt-ticket__barcode svg { height: 0.6in; }
	@media screen { .vt-tickets--thermal .vt-ticket { border: 1px dashed #999; margin: 0 auto 4mm; } }
{%- else %}
	@page { size: A4; margin: 8mm; }
{%- endif %}
</style>
<div class="vt-tickets vt-tickets--{{ data.format }}">
{%- for t in data.tickets %}
	<div class="vt-ticket">
		<div class="vt-ticket__head">
			<span class="vt-ticket__job">{{ t.garment_order | e }}</span>
			<span>{{ _("Bundle {0} of {1}").format(t.bundle_no_in_lot, t.bundles_in_lot) }}</span>
		</div>
		<div class="vt-ticket__barcode">{{ t.barcode | safe }}</div>
		<div class="vt-ticket__code">{{ t.name | e }}</div>
		<div class="vt-ticket__grid">
			<span>{{ _("Style") }}: <b>{{ t.style | e }}</b></span>
			<span>{{ _("Colour") }}: <b>{{ t.colour | e }}</b></span>
			<span>{{ _("Size") }}: <b>{{ t.size | e }}</b></span>
			<span>{{ _("Qty") }}: <span class="vt-ticket__qty">{{ t.qty }}</span></span>
			<span>{{ _("Job Map") }}: {{ t.job_map | e }}</span>
			<span>{{ doc.name | e }}</span>
		</div>
	</div>
{%- else %}
	<div class="vt-empty-tickets">{{ _("No bundles exist for this Cut Receive yet.") }}</div>
{%- endfor %}
</div>
